const {chromium}=require('C:/Users/human-01/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,channel:'msedge'});
 const page=await browser.newPage({viewport:{width:1440,height:1100}}); const errors=[], api=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('request',r=>{if(new URL(r.url()).pathname.startsWith('/api/')||r.url().includes('/rag-api/'))api.push(r.url());});
 await page.goto('http://127.0.0.1:3001/__design');
 const planner=page.locator('.weekly-planner');
 await planner.getByRole('button',{name:'나의 한 주 만들기'}).click();
 await planner.getByLabel('월요일 운동 가능 시작',{exact:true}).fill('20:00');
 await planner.getByLabel('월요일 운동 가능 종료',{exact:true}).fill('21:00');
 await planner.getByRole('button',{name:'샘플 주간 계획 만들기'}).click();
 await page.waitForFunction(()=>document.querySelectorAll('.planner-event').length===24);
 if(!await planner.locator('.planner-day').first().locator('.planner-event--exercise').innerText().then(t=>t.includes('20:00')))throw Error('exercise outside window');
 await planner.screenshot({path:'C:/Users/human-01/Desktop/stevil/data-collection/wegovy/rag/cache/planner-desktop.png'});
 await planner.getByRole('checkbox',{name:/완료$/}).first().check();
 await planner.getByRole('button',{name:'미리보기에서 확정'}).click();
 await planner.getByText('미리보기 안에서 저장했어요. 새로고침하면 초기화됩니다.').waitFor();
 await planner.getByRole('button',{name:'다음 주',exact:true}).click();
 await planner.getByRole('button',{name:'이전 주',exact:true}).click();
 await page.waitForFunction(()=>document.querySelectorAll('.planner-event').length===24);
 if(!await planner.getByRole('checkbox',{name:/완료$/}).first().isChecked())throw Error('completion not retained');
 await planner.locator('.planner-event > button').first().click();
 await planner.getByLabel('제목',{exact:true}).fill('수정한 식사');
 await planner.getByRole('button',{name:'미리보기에서 확정'}).click();
 await planner.getByRole('button',{name:'편집 닫기'}).click();
 await page.setViewportSize({width:390,height:844});
 await planner.screenshot({path:'C:/Users/human-01/Desktop/stevil/data-collection/wegovy/rag/cache/planner-mobile.png'});
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1);
 console.log(JSON.stringify({errors,unexpectedApiRequests:api,overflow}));
 await browser.close();if(errors.length||api.length||overflow)process.exitCode=1;
})();
